// Paper amplitude — GENERATED by scripts/derive-tokens.mjs, do not edit by hand.
//
// One constant perceptual step of OKLCH lightness, 0.0539 peak-to-peak, solved
// per band by bisection under a hard no-clipping constraint. The nominal target was
// 0.0541 (the #808080 mid-tone control); the light ground #f6f5f2 has only
// 0.0353 of headroom on its highest channel and caps it at 0.0539.
//
// The measurement each value carries is recorded in tokens/tokens.json under "paper".
export const AMPLITUDE = {
  "light": {
    "strength": 0.1687,
    "target": 0.0539,
    "achieved": 0.0539,
    "halfSwingSrgb": 0.0353,
    "headroomSrgb": 0.0353
  },
  "dark": {
    "strength": 0.1207,
    "target": 0.0539,
    "achieved": 0.0539,
    "halfSwingSrgb": 0.0252,
    "headroomSrgb": 0.1255
  }
};

// THE GROUNDS ARE EMITTED HERE TOO, and that is a fix rather than a convenience.
// tokens/paper.mjs used to name them itself — BANDS.light.ground = "#fbfaf7" — and
// when the ground ladder dropped to #f6f5f2 the amplitude solver moved and the
// texture module did not. Nothing broke visibly, because the page fills its rects
// with var(--paper); it was the MEASUREMENT harness that quietly went on measuring
// against a ground the system no longer uses. A value typed into two files is a
// value that will disagree with itself.
export const GROUNDS = {
  "light": "#f6f5f2",
  "dark": "#232320"
};
